def cap_per_key(keys: list[str], limit: int) -> list[int] | None:
    if type(limit) is not int or limit < 0: return None
    out=[]; counts={}
    for i,key in enumerate(keys):
        n=counts.get(key,0)
        if n < limit: out.append(i)
        counts[key]=n+1
    return out
